-- Read-only DDL extraction for schemas costing, public, app_private (catalog functions only)
with sch as (select oid, nspname from pg_namespace where nspname in ('costing','public','app_private')),
ext_objs as (select objid from pg_depend where deptype='e'),
types as (
 select 1 ord, 'type' kind, n.nspname||'.'||t.typname nm,
  case t.typtype when 'e' then format('create type %I.%I as enum (%s);',n.nspname,t.typname,(select string_agg(quote_literal(enumlabel),',' order by enumsortorder) from pg_enum where enumtypid=t.oid))
   when 'd' then format('create domain %I.%I as %s %s;',n.nspname,t.typname,format_type(t.typbasetype,t.typtypmod),coalesce((select string_agg(pg_get_constraintdef(c.oid),' ') from pg_constraint c where c.contypid=t.oid),''))
   when 'c' then format('create type %I.%I as (%s);',n.nspname,t.typname,(select string_agg(format('%I %s',a.attname,format_type(a.atttypid,a.atttypmod)),', ' order by attnum) from pg_attribute a where a.attrelid=t.typrelid and a.attnum>0 and not a.attisdropped)) end sql
 from pg_type t join sch n on n.oid=t.typnamespace
 where t.typtype in ('e','d') or (t.typtype='c' and (select relkind from pg_class where oid=t.typrelid)='c')
 and t.oid not in (select objid from ext_objs)),
seqs as (select 2, 'sequence', schemaname||'.'||sequencename, format('create sequence if not exists %I.%I;',schemaname,sequencename) from pg_sequences where schemaname in (select nspname from sch)),
tabs as (
 select 3, 'table', n.nspname||'.'||c.relname,
  format('create table %I.%I (%s);',n.nspname,c.relname,(select string_agg(format('%I %s%s%s%s',a.attname,format_type(a.atttypid,a.atttypmod),
     case a.attidentity when 'a' then ' generated always as identity' when 'd' then ' generated by default as identity' else '' end,
     case when a.attgenerated='s' then ' generated always as ('||pg_get_expr(d.adbin,d.adrelid)||') stored' when d.adbin is not null and a.attidentity='' then ' default '||pg_get_expr(d.adbin,d.adrelid) else '' end,
     case when a.attnotnull then ' not null' else '' end),', ' order by a.attnum)
   from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped))
 from pg_class c join sch n on n.oid=c.relnamespace where c.relkind in ('r','p') and c.oid not in (select objid from ext_objs)),
cons as (select 4, 'constraint', n.nspname||'.'||c.relname||'.'||k.conname, format('alter table %I.%I add constraint %I %s;',n.nspname,c.relname,k.conname,pg_get_constraintdef(k.oid))
 from pg_constraint k join pg_class c on c.oid=k.conrelid join sch n on n.oid=c.relnamespace where k.contype in ('p','u','c','x') and c.relkind in ('r','p')),
idx as (select 5, 'index', n.nspname||'.'||i.relname, pg_get_indexdef(i.oid)||';' from pg_index x join pg_class i on i.oid=x.indexrelid join pg_class c on c.oid=x.indrelid join sch n on n.oid=c.relnamespace
 where c.relkind in ('r','p','m') and not exists (select 1 from pg_constraint k where k.conindid=i.oid and k.contype in ('p','u','x'))),
fns as (select 6, 'function', n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')', pg_get_functiondef(p.oid)||';'
 from pg_proc p join sch n on n.oid=p.pronamespace where p.prokind in ('f','p') and p.oid not in (select objid from ext_objs)),
vws as (select 7, case c.relkind when 'v' then 'view' else 'matview' end, n.nspname||'.'||c.relname,
  case c.relkind when 'v' then format('create view %I.%I%s as %s',n.nspname,c.relname,case when c.reloptions is not null then ' with ('||array_to_string(c.reloptions,',')||')' else '' end,pg_get_viewdef(c.oid))
   else format('create materialized view %I.%I as %s with no data;',n.nspname,c.relname,rtrim(pg_get_viewdef(c.oid),';')) end
 from pg_class c join sch n on n.oid=c.relnamespace where c.relkind in ('v','m') and c.oid not in (select objid from ext_objs)),
fks as (select 8, 'fk', n.nspname||'.'||c.relname||'.'||k.conname, format('alter table %I.%I add constraint %I %s;',n.nspname,c.relname,k.conname,pg_get_constraintdef(k.oid))
 from pg_constraint k join pg_class c on c.oid=k.conrelid join sch n on n.oid=c.relnamespace where k.contype='f'),
trg as (select 9, 'trigger', n.nspname||'.'||c.relname||'.'||t.tgname, pg_get_triggerdef(t.oid)||';' from pg_trigger t join pg_class c on c.oid=t.tgrelid join sch n on n.oid=c.relnamespace where not t.tgisinternal)
select json_agg(json_build_object('o',ord,'k',kind,'n',nm,'s',sql,'h',md5(sql)) order by ord, nm) from (
 select * from types union all select * from seqs union all select * from tabs union all select * from cons union all select * from idx
 union all select * from fns union all select * from vws union all select * from fks union all select * from trg) x;
